// --- RVO (Unnamed return object) ---
HeavyObj create_obj() {
    return HeavyObj{}; // Compiler directly constructs in caller's space
}

HeavyObj main_obj = create_obj(); // No copy/move constructor called

// --- NRVO (Named return object) ---
HeavyObj create_named_obj() {
    HeavyObj result;
    // ... logic
    return result; // Compiler avoids copy/move if possible
}

// Optimization relies on object type:
// Requires C++17 guaranteed elision
// Pre-C++17: RVO possible, NRVO optional
// Modern C++: Copy/Move elided (zero overhead)
